const orderPattern = /\bord_[0-9A-Za-z]+\b/i;
const refundKeywords = ['退款', '退货', '换货', 'refund', 'return', 'exchange'];
const orderKeywords = ['订单', '物流', '发货', '配送', 'order', 'shipment', 'delivery'];
const referenceKeywords = ['这个订单', '该订单', '刚才那个订单', '上一单', 'this order'];

return $input.all().map((item) => {
  const text = String(item.json.input_text || '').trim();
  const lowered = text.toLowerCase();
  const match = text.match(orderPattern);
  const orderId = match ? match[0].toLowerCase() : '';
  const hasRefundIntent = refundKeywords.some((keyword) => lowered.includes(keyword));
  const hasAfterSalesIntent = refundKeywords.concat(orderKeywords).some((keyword) => lowered.includes(keyword));
  const hasOrderReference = referenceKeywords.some((keyword) => lowered.includes(keyword));
  const fastPathCandidate = Boolean((orderId && hasAfterSalesIntent) || hasRefundIntent || (hasOrderReference && hasAfterSalesIntent));

  return {
    json: {
      ...item.json,
      order_id: orderId,
      fast_path_candidate: fastPathCandidate,
      fast_path_body: {
        message_id: item.json.message_id,
        session_id: item.json.session_id,
        text,
        order_id: orderId || undefined,
        chat_id: item.json.chat_id,
        sender_id: item.json.sender_id
      }
    }
  };
});

